  let victim_key = #"deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef"
  let account_script_hash = #"1234567890abcdef1234567890abcdef1234567890abcdef123456"
  let input_ref = ref(0)
